/* The tables of M36 · Maintenance and helpdesk. */

export const ticketCategories = defineTable(
  'ticket_categories',
  { module: 'M36', scope: 'org' },
  {
    ...baseColumns,
    /** "Electrical", "Plumbing", "IT and projector" */
    name: text().notNull(),
    nameUr: text(),
    kind: enumText(ticketCategoryKinds).notNull(),
    /** a role key, such as `it_admin` */
    defaultAssigneeRole: text(),
    /** time to first action */
    responseHours: integer().notNull().default(4),
    /** time to fix */
    resolveHours: integer().notNull().default(48),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('ticket_categories_name_uq').on(t.orgId, t.name).where(live(t))],
);

/** Who gets a category's tickets at this branch. */
export const ticketAssignmentRules = defineTable(
  'ticket_assignment_rules',
  { module: 'M36', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    categoryId: uuid()
      .references((): AnyPgColumn => ticketCategories.id)
      .notNull(),
    assigneeStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
  },
  (t) => [
    uniqueIndex('ticket_assignment_rules_branch_category_uq')
      .on(t.branchId, t.categoryId)
      .where(live(t)),
  ],
);

export const maintenanceTickets = defineTable(
  'maintenance_tickets',
  { module: 'M36', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `ticket` sequence */
    ticketNo: text().notNull(),
    categoryId: uuid()
      .references((): AnyPgColumn => ticketCategories.id)
      .notNull(),
    title: text().notNull(),
    description: text(),
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    /** when there is no room record: "back gate" */
    place: text(),
    assetId: uuid().references((): AnyPgColumn => assets.id),
    priority: enumText(maintenanceTicketPriorities).notNull().default('normal'),
    isSafetyHazard: boolean().notNull().default(false),
    status: enumText(maintenanceTicketStatuses).notNull().default('open'),
    /** required for `waiting` */
    waitingReason: enumText(maintenanceTicketWaitingReasons),
    reportedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    assignedToStaffId: uuid().references((): AnyPgColumn => staff.id),
    /** when an outside contractor does the work */
    vendorId: uuid().references((): AnyPgColumn => vendors.id),
    /** from the category */
    respondBy: timestamptz().notNull(),
    resolveBy: timestamptz().notNull(),
    firstResponseAt: timestamptz(),
    resolvedAt: timestamptz(),
    closedAt: timestamptz(),
    /** required to resolve */
    resolution: text(),
    cost: paisa().notNull().default(0),
    expenseId: uuid().references((): AnyPgColumn => expenses.id),
    reporterRating: integer(),
    mergedIntoId: uuid().references((): AnyPgColumn => maintenanceTickets.id),
    /** when it was created by a routine schedule */
    scheduleId: uuid().references((): AnyPgColumn => preventiveSchedules.id),
  },
  (t) => [
    check(
      'maintenance_tickets_waiting_reason_needed',
      sql`${t.status} <> 'waiting' or ${t.waitingReason} is not null`,
    ),
    nonNegative('maintenance_tickets', t.cost),
    between('maintenance_tickets', t.reporterRating, 1, 5),
    index('maintenance_tickets_branch_status_priority_idx').on(
      t.orgId,
      t.branchId,
      t.status,
      t.priority,
    ),
    index('maintenance_tickets_assigned_to_staff_status_idx').on(
      t.orgId,
      t.assignedToStaffId,
      t.status,
    ),
    index('maintenance_tickets_reported_by_idx').on(t.orgId, t.reportedBy),
  ],
);

export const ticketComments = defineTable(
  'ticket_comments',
  { module: 'M36', scope: 'branch', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    ticketId: uuid()
      .references((): AnyPgColumn => maintenanceTickets.id)
      .notNull(),
    body: text(),
    authorId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** hidden from the reporter */
    isInternal: boolean().notNull().default(false),
    statusFrom: text(),
    statusTo: text(),
  },
);

/** Routine work that repeats: generator service, water tank cleaning, fire extinguisher check. */
export const preventiveSchedules = defineTable(
  'preventive_schedules',
  { module: 'M36', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    title: text().notNull(),
    categoryId: uuid()
      .references((): AnyPgColumn => ticketCategories.id)
      .notNull(),
    assetId: uuid().references((): AnyPgColumn => assets.id),
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    frequency: enumText(preventiveScheduleFrequencies).notNull(),
    nextDueOn: dateStr().notNull(),
    /** how early the ticket is created */
    leadDays: integer().notNull().default(3),
    assigneeStaffId: uuid().references((): AnyPgColumn => staff.id),
    /** `{ label }[]` */
    checklist: jsonb().notNull().default([]),
    isActive: boolean().notNull().default(true),
  },
);

export const facilityBookings = defineTable(
  'facility_bookings',
  { module: 'M36', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** a room marked bookable */
    roomId: uuid()
      .references((): AnyPgColumn => rooms.id)
      .notNull(),
    title: text().notNull(),
    purpose: text(),
    bookedByStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    startsAt: timestamptz().notNull(),
    /** the same day */
    endsAt: timestamptz().notNull(),
    attendees: integer(),
    /** projector, sound system, chairs */
    needs: text(),
    status: enumText(facilityBookingStatuses).notNull().default('requested'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decisionNote: text(),
  },
  (t) => [
    check('facility_bookings_ends_at_after', sql`${t.endsAt} > ${t.startsAt}`),
    index('facility_bookings_room_starts_at_idx').on(t.orgId, t.roomId, t.startsAt),
  ],
);
